-- Run in a NEW empty database. Data imported from the original import.xlsx.
SET XACT_ABORT ON;
BEGIN TRANSACTION;
CREATE TABLE [Roles$] (id int PRIMARY KEY, role nvarchar(50) NOT NULL);
CREATE TABLE [Sizes$] (id int PRIMARY KEY, [Размер] nvarchar(30) NOT NULL);
CREATE TABLE [Categories$] (id int PRIMARY KEY, [Категория] nvarchar(100) NOT NULL);
CREATE TABLE [Subcategories$] (id int PRIMARY KEY, [Подкатегория] nvarchar(100) NOT NULL);
CREATE TABLE [Manufactures$] (id int PRIMARY KEY, [Производство] nvarchar(200) NOT NULL);
CREATE TABLE [Products$] (id int PRIMARY KEY, id_category int REFERENCES [Categories$](id), id_subcategory int REFERENCES [Subcategories$](id), [Изображение] nvarchar(250), [Наименование товара] nvarchar(250) NOT NULL, id_manufactures int REFERENCES [Manufactures$](id), [Описание] nvarchar(max), [Состав] nvarchar(max), [Цена] decimal(18,2) NOT NULL CHECK ([Цена]>=0));
CREATE TABLE [Users$] (id int PRIMARY KEY, [Фамилия] nvarchar(100), [Имя] nvarchar(100), [Отчество] nvarchar(100), [Логин] nvarchar(100) NOT NULL UNIQUE, id_role int REFERENCES [Roles$](id));
CREATE TABLE [Stock_items$] (id int PRIMARY KEY, id_tovar int REFERENCES [Products$](id), id_sizes int REFERENCES [Sizes$](id), count int NOT NULL CHECK (count>=0));
CREATE TABLE [Orders_import$] (id int IDENTITY PRIMARY KEY, [Дата заказа] datetime2 NOT NULL, id_user int NOT NULL REFERENCES [Users$](id));
SET IDENTITY_INSERT Orders_import$ ON;
SET IDENTITY_INSERT Orders_import$ OFF;
CREATE TABLE [Order_stock$] (id_order int NOT NULL REFERENCES [Orders_import$](id), id_stock_items int NOT NULL REFERENCES [Stock_items$](id), [Количество] int NOT NULL CHECK ([Количество]>0));
COMMIT;
